#include <stdio.h>
#include <math.h>



int main(void) {
    double a, b, c;
    scanf("%lf%lf%lf", &a, &b, &c);
    double d = b * b - 4 * a * c;
    if (d >= 0) {
        double x = (-b - sqrt(d)) / (2 * a), y = (-b + sqrt(d)) / (2 * a);
        if (x > y) { double t = x; x = y; y = t; }
        printf("%.2f %.2f\n", fabs(x) < 0.000001 ? 0.0 : x, fabs(y) < 0.000001 ? 0.0 : y);
    } else {
        double real = -b / (2 * a), imaginary = sqrt(-d) / fabs(2 * a);
        if (fabs(real) < 0.000001) real = 0;
        printf("%.2f+%.2fi %.2f-%.2fi\n", real, imaginary, real, imaginary);
    }
    return 0;
}
